import { createReadStream } from 'node:fs';
import { appendFile, mkdir, readFile, rename, unlink, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { createInterface } from 'node:readline';
import { randomUUID } from 'node:crypto';

function identity(record) {
  if (record === null || typeof record !== 'object' || Array.isArray(record)
      || typeof record.tenant !== 'string' || !Number.isSafeInteger(record.seq)) {
    throw new Error('Event must have a string tenant and an integer seq');
  }
  return JSON.stringify([record.tenant, record.seq]);
}

async function* lines(path) {
  const stream = createReadStream(path, { encoding: 'utf8' });
  const reader = createInterface({ input: stream, crlfDelay: Infinity });
  // Forward stream errors to the iterator as well as closing resources on early exit.
  let error;
  const onError = (cause) => { error = cause; reader.close(); };
  stream.on('error', onError);
  try {
    for await (const line of reader) yield line;
    if (error) throw error;
  } finally {
    reader.close();
    stream.destroy();
    stream.removeListener('error', onError);
  }
}

async function loadCheckpoint(checkpointPath) {
  let text;
  try {
    text = await readFile(checkpointPath, 'utf8');
  } catch (error) {
    if (error.code === 'ENOENT') return 0;
    throw error;
  }
  try {
    const checkpoint = JSON.parse(text);
    if (!Number.isSafeInteger(checkpoint?.nextLine) || checkpoint.nextLine < 0) {
      throw new Error('Invalid checkpoint');
    }
    return checkpoint.nextLine;
  } catch {
    const recovery = join(dirname(checkpointPath), 'recovery');
    await mkdir(recovery, { recursive: true });
    const badPath = join(recovery, 'checkpoint.bad.json');
    // Preserve any earlier recovery evidence too.
    try {
      await writeFile(badPath, text, { flag: 'wx' });
    } catch (error) {
      if (error.code !== 'EEXIST') throw error;
      await writeFile(join(recovery, `checkpoint.bad.${randomUUID()}.json`), text, { flag: 'wx' });
    }
    await unlink(checkpointPath);
    return 0;
  }
}

async function saveCheckpoint(checkpointPath, nextLine) {
  const temporary = `${checkpointPath}.${randomUUID()}.tmp`;
  try {
    await writeFile(temporary, `${JSON.stringify({ nextLine })}\n`, { flag: 'wx' });
    await rename(temporary, checkpointPath);
  } finally {
    await unlink(temporary).catch((error) => {
      if (error.code !== 'ENOENT') throw error;
    });
  }
}

export async function processBatch({ inputPath, outputPath, checkpointPath, batchSize = 4 }) {
  if (!Number.isSafeInteger(batchSize) || batchSize < 1) {
    throw new RangeError('batchSize must be a positive integer');
  }
  await mkdir(dirname(outputPath), { recursive: true });
  await mkdir(dirname(checkpointPath), { recursive: true });
  const startLine = await loadCheckpoint(checkpointPath);
  const seen = new Set();
  try {
    for await (const line of lines(outputPath)) seen.add(identity(JSON.parse(line)));
  } catch (error) {
    if (error.code !== 'ENOENT') throw error;
  }

  const report = { accepted: 0, rejected: 0, duplicates: 0, nextLine: startLine };
  const rejectedPath = join(dirname(outputPath), 'rejected.ndjson');
  let lineNumber = 0;
  for await (const line of lines(inputPath)) {
    if (lineNumber++ < startLine) continue;
    let key;
    try {
      key = identity(JSON.parse(line));
    } catch {
      await appendFile(rejectedPath, `${line}\n`);
      report.rejected++;
      report.nextLine = lineNumber;
      continue;
    }
    if (seen.has(key)) {
      report.duplicates++;
    } else {
      await appendFile(outputPath, `${line}\n`);
      seen.add(key);
      report.accepted++;
    }
    report.nextLine = lineNumber;
    if (report.accepted === batchSize) break;
  }
  await saveCheckpoint(checkpointPath, report.nextLine);
  return report;
}

// Usage: node bin/ingest.mjs INPUT OUTPUT CHECKPOINT [BATCH_SIZE]
import { processBatch } from '../src/ingest.mjs';

const args = process.argv.slice(2);
if (args.length < 3 || args.length > 4) {
  console.error('Usage: node bin/ingest.mjs INPUT OUTPUT CHECKPOINT [BATCH_SIZE]');
  process.exitCode = 1;
} else {
  const [inputPath, outputPath, checkpointPath, size] = args;
  try {
    const report = await processBatch({
      inputPath, outputPath, checkpointPath,
      ...(size === undefined ? {} : { batchSize: Number(size) }),
    });
    console.log(JSON.stringify(report));
  } catch (error) {
    console.error(error.message);
    process.exitCode = 1;
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, writeFile, readFile, rm } from 'node:fs/promises';
import { join } from 'node:path';
import { processBatch } from '../src/ingest.mjs';

async function workspace(run) {
  const dir = await mkdtemp(join(process.cwd(), '.ingest-test-'));
  const paths = { inputPath: join(dir, 'input.ndjson'), outputPath: join(dir, 'output.ndjson'), checkpointPath: join(dir, 'checkpoint.json') };
  try { await run(paths, dir); } finally { await rm(dir, { recursive: true, force: true }); }
}
const event = (tenant, seq) => JSON.stringify({ tenant, seq, value: `original-${seq}` });

test('default counts accepted records, quarantines errors, and resumes at EOF', async () => {
  await workspace(async (paths, dir) => {
    const records = [event('a', 1), 'broken', event('b', 1), event('a', 1), event('a', 2), event('a', 3), event('a', 4)];
    await writeFile(paths.inputPath, records.join('\n') + '\n');
    assert.deepEqual(await processBatch(paths), { accepted: 4, rejected: 1, duplicates: 1, nextLine: 6 });
    assert.equal(await readFile(join(dir, 'rejected.ndjson'), 'utf8'), 'broken\n');
    assert.deepEqual(await processBatch(paths), { accepted: 1, rejected: 0, duplicates: 0, nextLine: 7 });
    assert.deepEqual(await processBatch(paths), { accepted: 0, rejected: 0, duplicates: 0, nextLine: 7 });
    assert.equal(await readFile(paths.outputPath, 'utf8'), [records[0], records[2], records[4], records[5], records[6]].join('\n') + '\n');
  });
});

test('corrupt checkpoint preserves evidence and existing output during replay', async () => {
  await workspace(async (paths, dir) => {
    const records = [event('a', 1), event('b', 1), event('a', 2)];
    await writeFile(paths.inputPath, records.join('\n'));
    await writeFile(paths.outputPath, records[0] + '\n');
    await writeFile(paths.checkpointPath, '{bad');
    assert.deepEqual(await processBatch(paths), { accepted: 2, rejected: 0, duplicates: 1, nextLine: 3 });
    assert.equal(await readFile(join(dir, 'recovery/checkpoint.bad.json'), 'utf8'), '{bad');
    assert.equal(await readFile(paths.outputPath, 'utf8'), records.join('\n') + '\n');
    assert.deepEqual(JSON.parse(await readFile(paths.checkpointPath, 'utf8')), { nextLine: 3 });
  });
});

test('missing checkpoint replays existing output without duplication; invalid batch fails', async () => {
  await workspace(async (paths) => {
    await writeFile(paths.inputPath, event('a', 1) + '\n' + event('b', 1) + '\n');
    await writeFile(paths.outputPath, event('a', 1) + '\n');
    assert.deepEqual(await processBatch({ ...paths, batchSize: 1 }), { accepted: 1, rejected: 0, duplicates: 1, nextLine: 2 });
    await assert.rejects(processBatch({ ...paths, batchSize: 0 }), RangeError);
  });
});

